xql_query:
// ============================================================
// Rule: GIT_Repository Unarchived
// Vendor: GIT
// Objective:
// Detect activity associated with GIT_Repository Unarchived.
// Severity: SEV_040_HIGH
// Category: OTHER
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0002 - Execution
// Technique: T1677 - Poisoned Pipeline Execution

// Fonte: logs brutos do GitHub
dataset = github_github_raw

// Apenas eventos de mudança de status do repositório
| filter action in ("archived", "unarchived")

// Normaliza os campos relevantes a partir do JSON do GitHub
| alter
    repo_full_name   = repository -> full_name,
    repo_name        = repository -> name,
    repo_archived    = repository -> archived,
    org_login        = organization -> login,
    actor_login      = sender -> login,
    enterprise_slug  = enterprise -> slug,
    evento_status    = action

// Agrupa por repositório e verifica se houve mais de um status (archived + unarchived)
| comp
    count_distinct(evento_status) as qtd_status_diferentes,
    values(evento_status)         as status_observados,
    values(actor_login)           as atores,
    values(org_login)             as organizacoes,
    values(enterprise_slug)       as enterprises,
    min(_time)                    as primeiro_evento,
    max(_time)                    as ultimo_evento,
    count(evento_status)          as total_eventos
  by repo_full_name

// Só interessa quando o repositório teve mudança de status (antes e depois)
| filter qtd_status_diferentes > 1

// Ordena pelos mais recentes
| sort desc ultimo_evento

| fields 
    repo_full_name,
    status_observados,
    qtd_status_diferentes,
    total_eventos,
    primeiro_evento,
    ultimo_evento,
    atores,
    organizacoes,
    enterprises
